const src = $input.first().json || {};
const rawText = src?.choices?.[0]?.message?.content || '';

// 1) Model failed (HTTP error, timeout, blocked, empty). Not the photo's fault.
if (src.error || !rawText.trim()) {
  return [{ json: { model_error: true, parse_ok: false, needs_review: false, unclear_text: '', extracted: {} } }];
}

// 2) Find the JSON object inside the text, even if there is extra chatter around it
const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '');
let data = {};
let parse_ok = true;
try {
  const s = cleaned.indexOf('{');
  const e = cleaned.lastIndexOf('}');
  data = JSON.parse(cleaned.slice(s, e + 1));
  if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error('Not an object');
} catch (err) {
  parse_ok = false;
  data = {};
}

const arr = (v) => (Array.isArray(v) ? v.filter((x) => x && typeof x === 'object') : []);
const str = (v) => (v === null || v === undefined ? '' : String(v).trim());
const isLow = (v) => {
  if (v === null || v === undefined || v === '') return true;
  const n = Number(v);
  return Number.isNaN(n) || n < 0.7;
};
const isDate = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && !Number.isNaN(Date.parse(s + 'T00:00:00Z'));

const events = arr(data.events);
const deadlines = arr(data.deadlines);
const amounts = arr(data.amounts);
const docs = arr(data.documents_required);
const modelUnclear = Array.isArray(data.unclear_items) ? data.unclear_items.map((x) => str(x)).filter(Boolean) : [];

// 3) needs_review flags
const lowConfidence =
  events.some((e) => isLow(e.confidence)) ||
  deadlines.some((d) => isLow(d.confidence)) ||
  amounts.some((a) => isLow(a.confidence));
const badDate = events.some((e) => !isDate(e.date_iso)) || deadlines.some((d) => !isDate(d.date_iso));
const nothingFound = events.length + deadlines.length + amounts.length + docs.length === 0;
const needs_review = !parse_ok || lowConfidence || badDate || nothingFound;

// 4) What was unclear
const unclear = [];
if (!parse_ok) unclear.push('The model reply could not be read as structured data.');
if (parse_ok && nothingFound) unclear.push('No events, deadlines, fees or documents could be read from the photo.');
events.forEach((e) => {
  const label = str(e.name) || 'an event';
  if (isLow(e.confidence)) unclear.push('Event "' + label + '": confidence is low or missing.');
  if (!isDate(e.date_iso)) unclear.push('Event "' + label + '": date not clear.');
});
deadlines.forEach((d) => {
  const label = str(d.what) || 'a deadline';
  if (isLow(d.confidence)) unclear.push('Deadline "' + label + '": confidence is low or missing.');
  if (!isDate(d.date_iso)) unclear.push('Deadline "' + label + '": date not clear.');
});
amounts.forEach((a) => {
  if (isLow(a.confidence)) unclear.push('Fee "' + (str(a.purpose) || 'a fee') + '": confidence is low or missing.');
});
modelUnclear.forEach((u) => unclear.push('Model note: ' + u));

const unclear_text = unclear.map((u) => '- ' + u).join('\n');

return [{ json: { model_error: false, parse_ok, needs_review, unclear_text, extracted: data } }];

