const notice = $input.first().json.extracted || {};
const events = Array.isArray(notice.events) ? notice.events.filter((e) => e && typeof e === 'object') : [];

// Today in Asia/Kolkata
const parts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date());
const pick = (type) => Number(parts.find((p) => p.type === type).value);
const todayMs = Date.UTC(pick('year'), pick('month') - 1, pick('day'));
const isDate = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && !Number.isNaN(Date.parse(s + 'T00:00:00Z'));

if (events.length === 0) {
  return [{ json: { idx: 0, is_placeholder: true, has_venue: false, date_ok: false, days_ahead: null } }];
}

return events.map((event, idx) => {
  const venue = typeof event.venue === 'string' ? event.venue.trim() : '';
  const date_ok = isDate(event.date_iso);
  const days_ahead = date_ok ? Math.round((Date.parse(event.date_iso + 'T00:00:00Z') - todayMs) / 86400000) : null;
  return { json: { idx, event, has_venue: venue.length > 0, date_ok, days_ahead, is_placeholder: false } };
});

const original = $('Explode Events').item.json;
const res = $input.item.json || {};
const venue = typeof original.event?.venue === 'string' ? original.event.venue.trim() : '';
const r = Array.isArray(res.results) ? res.results[0] : null;

if (res.status === 'OK' && r && r.geometry && r.geometry.location) {
  const formatted = r.formatted_address || venue;
  const place_id = r.place_id || '';
  const maps_url = 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(formatted)
    + (place_id ? '&query_place_id=' + place_id : '');
  return { json: { ...original, geo_ok: true, formatted_address: formatted, lat: r.geometry.location.lat, lng: r.geometry.location.lng, place_id, maps_url } };
}

return { json: { ...original, geo_ok: false, formatted_address: null, lat: null, lng: null, place_id: null,
  maps_url: 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(venue) } };

const original = $('Merge Geo').item.json;
const res = $input.item.json || {};
const day = res.daily;
let weather_text = null;

if (day && Array.isArray(day.time) && day.time[0]) {
  const tmax = Array.isArray(day.temperature_2m_max) ? day.temperature_2m_max[0] : null;
  const rain = Array.isArray(day.precipitation_probability_max) ? day.precipitation_probability_max[0] : null;
  const parts = [];
  if (typeof tmax === 'number') parts.push('up to ' + Math.round(tmax) + 'C');
  if (typeof rain === 'number') parts.push('rain chance ' + Math.round(rain) + '%');
  if (parts.length) {
    weather_text = 'Forecast: ' + parts.join(', ');
    if (typeof rain === 'number' && rain >= 50) weather_text += ' - carry an umbrella';
  }
}

return { json: { ...original, weather_text } };

const IST_OFFSET_MS = 330 * 60000;
const pad = (n) => String(n).padStart(2, '0');
const str = (v) => (v === null || v === undefined ? '' : String(v).trim());
const esc = (v, fb) => str(v) || fb;
const quote = (s) => '"' + esc(s, 'no source line') + '"';
const isDate = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && !Number.isNaN(Date.parse(s + 'T00:00:00Z'));
const arr = (v) => (Array.isArray(v) ? v.filter((x) => x && typeof x === 'object') : []);
const parseTime = (t) => {
  const s = str(t).toLowerCase();
  const m = s.match(/^(\d{1,2})(?:[:.](\d{2}))?\s*([ap])?\.?\s*(m\.?)?$/);
  if (!m) return null;
  let h = Number(m[1]);
  const min = m[2] ? Number(m[2]) : 0;
  if (m[3] === 'p' && h < 12) h += 12;
  if (m[3] === 'a' && h === 12) h = 0;
  if (h > 23 || min > 59) return null;
  return { h, min };
};
const addDay = (iso) => {
  const [y, mo, d] = iso.split('-').map(Number);
  const dt = new Date(Date.UTC(y, mo - 1, d + 1));
  return dt.getUTCFullYear() + '-' + pad(dt.getUTCMonth() + 1) + '-' + pad(dt.getUTCDate());
};
const fmtIst = (ms) => {
  const s = new Date(ms + IST_OFFSET_MS);
  return s.getUTCFullYear() + '-' + pad(s.getUTCMonth() + 1) + '-' + pad(s.getUTCDate())
    + 'T' + pad(s.getUTCHours()) + ':' + pad(s.getUTCMinutes()) + ':00+05:30';
};

const items = $input.all().map((i) => i.json)
  .filter((j) => j && typeof j === 'object')
  .sort((a, b) => (a.idx ?? 0) - (b.idx ?? 0));
const notice = ($('Parse And Build').first().json || {}).extracted || {};
const eventItems = items.filter((i) => !i.is_placeholder && i.event);
const deadlines = arr(notice.deadlines);
const amounts = arr(notice.amounts);
const docs = arr(notice.documents_required);
const applies = notice.applies_to && typeof notice.applies_to === 'object' && !Array.isArray(notice.applies_to) ? notice.applies_to : {};
const title = str(notice.title);

const appliesParts = [];
if (applies.all_students === true) appliesParts.push('All students');
const classes = Array.isArray(applies.classes) ? applies.classes.map((c) => str(c)).filter(Boolean) : [];
if (classes.length) appliesParts.push('Classes: ' + classes.join(', '));

const hasAmt = (a) => a.amount_inr !== null && a.amount_inr !== undefined && a.amount_inr !== '';
const placeOf = (it) => (it.geo_ok === true && it.formatted_address ? str(it.formatted_address) : str(it.event.venue));

// ---- reply_text ----
const out = [];
out.push('Notice summary' + (title ? ': ' + title : ''));
if (str(notice.document_type)) out.push('Type: ' + str(notice.document_type));
if (str(notice.language_detected)) out.push('Language: ' + str(notice.language_detected));
out.push('');

if (eventItems.length) {
  out.push('EVENTS');
  eventItems.forEach((it) => {
    const e = it.event;
    const place = it.geo_ok === true && it.formatted_address
      ? str(it.formatted_address) + ' (verified on Google Maps)'
      : str(e.venue);
    out.push('- ' + esc(e.name, 'Event') + ' | ' + esc(e.date_iso, 'date not clear') + (str(e.time) ? ' at ' + str(e.time) : ''));
    if (place) out.push('   Venue: ' + place);
    if (it.maps_url) out.push('   Map: ' + it.maps_url);
    if (it.weather_text) out.push('   Weather: ' + it.weather_text);
    out.push('   ' + quote(e.source_line));
  });
  out.push('');
}

if (deadlines.length) {
  out.push('DEADLINES');
  deadlines.forEach((d) => {
    out.push('- ' + esc(d.what, 'Deadline') + ' | ' + esc(d.date_iso, 'date not clear'));
    out.push('   ' + quote(d.source_line));
  });
  out.push('');
}

if (amounts.length) {
  out.push('FEES');
  amounts.forEach((a) => {
    const amt = hasAmt(a) ? 'INR ' + a.amount_inr : 'amount not clear';
    out.push('- ' + esc(a.purpose, 'Payment') + ': ' + amt + (isDate(a.due_date_iso) ? ' | due ' + a.due_date_iso : ''));
    out.push('   ' + quote(a.source_line));
  });
  out.push('');
}

if (docs.length) {
  out.push('DOCUMENTS NEEDED');
  docs.forEach((d) => {
    out.push('- ' + esc(d.item, 'Item'));
    out.push('   ' + quote(d.source_line));
  });
  out.push('');
}

if (appliesParts.length || str(applies.source_line)) {
  out.push('APPLIES TO');
  out.push('- ' + (appliesParts.join('; ') || 'not clear'));
  out.push('   ' + quote(applies.source_line));
  out.push('');
}

const footer = 'Always check the original notice before acting.';
out.push(footer);
let reply_text = out.join('\n').trim();
if (reply_text.length > 3900) {
  const body = out.slice(0, -1).join('\n');
  reply_text = body.slice(0, 3700).trim() + '\n...(cut short to fit Telegram)\n' + footer;
}

// ---- calendar_items ----
const calendar_items = [];
eventItems.forEach((it) => {
  const e = it.event;
  if (!isDate(e.date_iso)) return;
  const location = placeOf(it);
  const description = str(e.source_line);
  const name = esc(e.name, 'Event');
  const t = parseTime(e.time);
  if (t) {
    const [y, mo, d] = e.date_iso.split('-').map(Number);
    const startMs = Date.UTC(y, mo - 1, d, t.h, t.min) - IST_OFFSET_MS;
    calendar_items.push({ title: name, start: fmtIst(startMs), end: fmtIst(startMs + 3600000), all_day: false, location, description });
  } else {
    calendar_items.push({ title: name, start: e.date_iso, end: addDay(e.date_iso), all_day: true, location, description });
  }
});
deadlines.forEach((d) => {
  if (!isDate(d.date_iso)) return;
  calendar_items.push({
    title: 'Deadline: ' + esc(d.what, 'Deadline'),
    start: d.date_iso,
    end: addDay(d.date_iso),
    all_day: true,
    location: '',
    description: str(d.source_line)
  });
});

// ---- approval_text ----
const whenOf = (c) => (c.all_day ? c.start : c.start.slice(0, 10) + ' ' + c.start.slice(11, 16));
const n = calendar_items.length;
const approval_text = n
  ? (n === 1 ? 'Add this 1 date to your calendar? ' : 'Add these ' + n + ' dates to your calendar? ')
    + calendar_items.map((c) => c.title + ' (' + whenOf(c) + ')').join('; ') + '.'
  : '';

// ---- facts_for_groq ----
const facts = [];
facts.push('Document: ' + (title || 'untitled') + (str(notice.document_type) ? ' (' + str(notice.document_type) + ')' : ''));
if (eventItems.length) {
  facts.push('Events:');
  eventItems.forEach((it) => {
    const e = it.event;
    const place = placeOf(it);
    facts.push('- ' + esc(e.name, 'Event') + ', ' + esc(e.date_iso, 'date unclear')
      + (str(e.time) ? ' at ' + str(e.time) : '')
      + (place ? ', venue: ' + place : '')
      + (it.weather_text ? ', ' + it.weather_text : ''));
  });
}
if (deadlines.length) {
  facts.push('Deadlines:');
  deadlines.forEach((d) => facts.push('- ' + esc(d.what, 'Deadline') + ', ' + esc(d.date_iso, 'date unclear')));
}
if (amounts.length) {
  facts.push('Fees:');
  amounts.forEach((a) => facts.push('- ' + esc(a.purpose, 'Payment') + ': '
    + (hasAmt(a) ? 'INR ' + a.amount_inr : 'amount unclear')
    + (isDate(a.due_date_iso) ? ', due ' + a.due_date_iso : '')));
}
if (docs.length) facts.push('Documents needed: ' + docs.map((d) => esc(d.item, 'item')).join('; '));
if (appliesParts.length) facts.push('Applies to: ' + appliesParts.join('; '));
const facts_for_groq = facts.join('\n');

return [{ json: { reply_text, calendar_items, calendar_count: n, approval_text, facts_for_groq } }];

const items = $input.all().map((i) => i.json || {});
const ok = items.filter((i) => i.htmlLink);
const failed = items.length - ok.length;
let text;
if (ok.length === 0) {
  text = 'Could not add any events to your calendar. Please add them by hand.';
} else {
  text = 'Added ' + ok.length + ' event(s) to your calendar:\n'
    + ok.map((i) => '- ' + (i.summary || 'Event') + ': ' + i.htmlLink).join('\n');
  if (failed > 0) text += '\nCould not add ' + failed + '. Please add them by hand.';
}
return [{ json: { text } }];

const msg = $input.first().json || {};
const text = String(msg?.message?.text ?? '').trim();
const WELCOME = 'Send me a photo of a school notice and I will pull out dates, fees, venue maps and calendar events. Nothing is added without your approval.';
const isStart = /^\/(start|help)(@\S+)?(\s|$)/i.test(text);
const route = !text || isStart ? 'static' : 'groq';
return [{ json: { route, welcome_text: WELCOME, user_text: text } }];
